b:if.script:
//
document.addEventListener('DOMContentLoaded', function() {
  var postBody = document.querySelector('.post-body');
  var timeDisplay = document.querySelector('.reading-time-num');
  if (postBody && timeDisplay) {
    var text = postBody.innerText || postBody.textContent || '';
    var words = text.trim().split(/\s+/).filter(Boolean).length;
    var minutes = Math.max(1, Math.ceil(words / 200));
    timeDisplay.textContent = minutes;
  }

  // Ubicar la barra de compartir exactamente debajo de la imagen de portada
  var shareBar = document.getElementById('editorial-post-share-bar');
  if (postBody && shareBar) {
    var firstImg = postBody.querySelector('.separator:first-child') ||
                   postBody.querySelector('p:first-child img, div:first-child img, a:first-child img, img:first-child') ||
                   postBody.querySelector('img');
    if (firstImg) {
      var coverElement = firstImg.closest('.separator') || 
                         (firstImg.parentElement && firstImg.parentElement.tagName === 'A' && firstImg.parentElement.parentElement === postBody ? firstImg.parentElement : null) ||
                         (firstImg.parentElement === postBody ? firstImg : firstImg.closest('p') || firstImg);
      if (coverElement && coverElement.parentNode === postBody) {
        coverElement.insertAdjacentElement('afterend', shareBar);
      }
    }
  }
});
//
